#!/bin/sh
# logi-claude-desktop-statusline — generated by the Claude plugin. Rewritten on every load.
# Claude Code pipes the status line JSON on stdin. stdout is the user's status bar,
# so nothing in here may ever print to it.
curl -s --connect-timeout 0.5 -m 2 \
  -H 'Content-Type: application/json' --data-binary @- \
  'http://localhost:8765/statusline' >/dev/null 2>&1 || true
exit 0
